(()=>{if(window.sayReady)return;window.sayReady=!0;let e;document.addEventListener("click",t=>{const n=t.target.closest("[data-say]");if(!n)return;if(!e){e=document.createElement("dialog"),e.className="say-dialog",e.setAttribute("aria-label","Say something"),e.innerHTML='<form method="dialog"><button class="say-close" aria-label="Close">×</button></form><div class="say-body"><h2>Say something</h2><div class="giscus"></div></div>',e.addEventListener("click",t=>{t.target===e&&e.close()}),document.body.append(e);const t=document.createElement("script");t.src="https://giscus.app/client.js";for(const[e,s]of Object.entries(JSON.parse(n.dataset.say)))t.setAttribute("data-"+e,s);t.crossOrigin="anonymous",t.async=!0,e.querySelector(".say-body").append(t)}e.showModal()})})()